for game in GAMES:
    game["cover"] = f"/static/covers/{COVER_FILES[game['id']]}"


def recommend_games(genre: str, pc_level: str, budget: int) -> list[dict]:
    """Return affordable games matching the requested genre and PC profile."""
    if genre not in GENRES[1:] or pc_level not in LEVELS or budget < 0:
        return []
    compatible = [
        game for game in GAMES
        if game["genre"] == genre
        and LEVELS[game["level"]] <= LEVELS[pc_level]
        and game["price"] <= budget
    ]
    return sorted(compatible, key=lambda game: (game["price"], game["name"]))[:5]
